import heapq


def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        names = sorted(packages)
        constraints = {name: [tuple(bounds) for bounds in data["roots"].values()]
                       for name in ()}
        constraints = {name: [tuple(data["roots"][name])]
                       for name in data["roots"]}
        best = None
        best_key = None

        def visit(chosen, required, edges):
            nonlocal best, best_key
            for name, ranges in required.items():
                if name in chosen and any(not (lo <= chosen[name] <= hi)
                                          for lo, hi in ranges):
                    return
            unresolved = [name for name in required if name not in chosen]
            if not unresolved:
                state = {}
                def cyclic(node):
                    if state.get(node) == 1:
                        return True
                    if state.get(node) == 2:
                        return False
                    state[node] = 1
                    if any(cyclic(nxt) for nxt in edges.get(node, ())):
                        return True
                    state[node] = 2
                    return False
                if any(cyclic(name) for name in chosen if state.get(name) != 2):
                    return
                vector = tuple(chosen[name] if name in chosen else -1
                               for name in (names if name_order == "ascending" else names[::-1]))
                key = tuple(vector if preference == "minimum" else (-v for v in vector))
                if best_key is None or key < best_key:
                    best_key, best = key, dict(chosen)
                return
            name = unresolved[0]
            ranges = required[name]
            rows = []
            for row in packages.get(name, []):
                version = row["version"]
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                if all(lo <= version <= hi for lo, hi in ranges):
                    rows.append(row)
            rows.sort(key=lambda r: r["version"], reverse=(preference == "maximum"))
            for row in rows:
                version = row["version"]
                new_required = {n: list(rs) for n, rs in required.items()}
                new_edges = {n: list(es) for n, es in edges.items()}
                active = [dep for dep in row.get("deps", [])
                          if not dep.get("feature") or dep.get("feature") in features]
                new_edges[name] = [dep["name"] for dep in active]
                valid = True
                for dep in active:
                    depname = dep["name"]
                    new_required.setdefault(depname, []).append((dep["min"], dep["max"]))
                    if depname in chosen and not dep["min"] <= chosen[depname] <= dep["max"]:
                        valid = False
                        break
                if valid:
                    new_chosen = dict(chosen)
                    new_chosen[name] = version
                    visit(new_chosen, new_required, new_edges)

        visit({}, {n: [tuple(b)] for n, b in data["roots"].items()}, {})
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if ident not in winners or key > winners[ident][0]:
            winners[ident] = (key, event)

    def rounded(n, d, mode):
        if mode == "half_up":
            return (2 * n + d) // (2 * d)
        return n // d

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, data["rounding"])
        tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    jobs = [job for job in jobs if job["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    for subset in combinations(jobs, k):
        ids = sorted(job["id"] for job in subset)
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    start_mask = bit.get(start_node, 0)
    start = (data["start"], start_node, 0, start_mask)
    queue = [start]
    distance = {(start_node, 0, start_mask): data["start"]}
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    while queue:
        time, node, used, mask = heapq.heappop(queue)
        state = (node, used, mask)
        if distance.get(state) != time:
            continue
        if node == data["target"] and used == data["coupons"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, used + 1))
            for duration, next_used in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                next_state = (nxt, next_used, next_mask)
                if arrival < distance.get(next_state, float("inf")):
                    distance[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_used, next_mask))
    return {"arrival": None}


